      statusText.textContent = '✅ 已是最新书源咯～';
    }

    loading.style.display = 'none';
    container.style.display = 'block';

  } catch (err) {
    loading.textContent = '😢 检查失败啦～ 请稍后再试==>'+err;
    console.error('版本检查失败：', err);
  }
})();
</script>
</body>
</html>
`;
  java.startBrowser(`data:text/html;base64,${java.base64Encode(html)}`, '大灰狼书源更新');
}

